var promptRotateTimer = null;
var promptRotateGroup = 0;

function shuffleArray(arr) {
  var a = arr.slice();
  for (var i = a.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}

function renderPrompts() {
  var el = document.getElementById('aiPromptList');
  if (!el) return;
  // 每次刷新取 4 个随机提示
  var picks = shuffleArray(AI_PROMPTS).slice(0, 4);
  el.innerHTML = picks.map(function(p) {
    var safeQ = p.q.replace(/'/g, '\\\'').replace(/"/g, '&quot;');
    return '<div class="ai-prompt fade-in" onclick="askAi(\'' + safeQ + '\')">' + p.text + '</div>';
  }).join('');
}

function startPromptRotation() {
  if (promptRotateTimer) clearInterval(promptRotateTimer);
  renderPrompts();
  // 每 2 分钟（120000ms）轮换一次
  promptRotateTimer = setInterval(function() {
    promptRotateGroup = (promptRotateGroup + 1) % 4;
    renderPrompts();
  }, 120000);
}

function renderSummary(l1, l2) {
  const html = `
    <div class="summary-card sc-red"><div class="sc-num">${l1}</div><div class="sc-label">红色高危（必须修改）</div></div>
    <div class="summary-card sc-yellow"><div class="sc-num">${l2}</div><div class="sc-label">黄色预警（需提供证明）</div></div>
    <div class="summary-card sc-green"><div class="sc-num">${l1 === 0 && l2 === 0 ? '✓' : '-'}</div><div class="sc-label">${l1 === 0 && l2 === 0 ? '可以发布' : '需修改后发布'}</div></div>
  `;
  document.getElementById('summary').innerHTML = html;
}

function renderViolations(violations) {
  if (violations.length === 0) {
    document.getElementById('violationList').innerHTML = '<div class="empty">未检测到违规词，文案可以发布。<br>注意：本工具仅检测已知违规词，新型表述请人工复核。</div>';
    return;
  }

  const html = violations.map((v, i) => {
    const isL1 = v.riskLevel === 'L1';
    const cls = isL1 ? 'v-red' : 'v-yellow';
    const badge = isL1 ? 'L1 拦截级' : 'L2 预警级';
    const catName = CATEGORY_NAMES[v.category] || v.category;

    let legalHtml = '';
    if (v.legalBasis && v.legalBasis.length > 0) {
      legalHtml = v.legalBasis.map(l => `<div class="v-legal">《${escapeHtml(l.law_name)}》${escapeHtml(l.article || '')}<br>${escapeHtml(l.content || '')}</div>`).join('');
    }

    let altHtml = '';
    if (v.alternatives && v.alternatives.length > 0) {
      const words = v.alternatives.map(a => `<span class="suggest-word" onclick="copyText('${escapeHtml(a).replace(/'/g,"\'")}')">${escapeHtml(a)}</span>`).join('');
      altHtml = `<div class="v-suggest"><div class="v-suggest-label">建议替换为（点击可复制）：</div><div class="v-suggest-words">${words}</div><div class="copy-tip">点击任意建议词即可复制到剪贴板</div></div>`;
    } else {
      altHtml = `<div class="v-suggest" style="background:#f5f5f7;"><div class="v-suggest-label" style="color:#6e6e73;">暂无替换建议，建议直接删除该词</div></div>`;
    }

    let noteHtml = '';
    if (v.note) {
      noteHtml = `<div class="v-note">说明：${escapeHtml(v.note)}</div>`;
    }

    let whitelistHtml = '';
    if (v.whitelist && v.whitelist.length > 0) {
      whitelistHtml = `<div class="v-whitelist">白名单（以下情况可使用）：${v.whitelist.map(w => escapeHtml(w)).join('；')}</div>`;
    }

    const wordDisplay = v.word === v.mainWord ? escapeHtml(v.word) : `${escapeHtml(v.word)} <span style="font-size:12px;color:#6e6e73;">（属于"${escapeHtml(v.mainWord)}"的变体）</span>`;

    return `<div class="violation ${cls}">
      <div class="v-header">
        <span class="v-word">${wordDisplay}</span>
        <span class="v-badge">${badge}</span>
      </div>
      <div class="v-field"><span class="v-field-label">分类：</span>${escapeHtml(catName)}</div>
      <div class="v-field"><span class="v-field-label">原因：</span>${escapeHtml(v.description)}</div>
      ${legalHtml}
      ${noteHtml}
      ${altHtml}
      ${whitelistHtml}
    </div>`;
  }).join('');

  document.getElementById('violationList').innerHTML = html;
}

function renderPreview(text, ranges) {
  if (ranges.length === 0) {
    document.getElementById('previewSection').classList.add('hidden');
    return;
  }
  document.getElementById('previewSection').classList.remove('hidden');

  ranges.sort((a, b) => a.start - b.start);
  let html = '';
  let lastEnd = 0;
  const seen = new Set();
  const filtered = ranges.filter(r => {
    const key = r.start + '-' + r.end;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  filtered.forEach(r => {
    html += escapeHtml(text.substring(lastEnd, r.start));
    const cls = r.risk === 'L1' ? 'red' : 'yellow';
    html += `<mark class="${cls}">${escapeHtml(text.substring(r.start, r.end))}</mark>`;
    lastEnd = r.end;
  });
  html += escapeHtml(text.substring(lastEnd));
  document.getElementById('preview').innerHTML = html;
}

function copyText(text) {
  if (navigator.clipboard) {
    navigator.clipboard.writeText(text).then(() => showToast('已复制：' + text));
  } else {
    const ta = document.createElement('textarea');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); showToast('已复制：' + text); } catch(e) { showToast('复制失败，请手动复制'); }
    document.body.removeChild(ta);
  }
}

function showToast(msg) {
  let toast = document.getElementById('toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'toast';
    toast.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#1A1817;color:#fff;padding:10px 24px;border-radius:8px;font-size:13px;z-index:9999;box-shadow:0 4px 16px rgba(26,24,23,0.25);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;font-weight:500;';
    document.body.appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.opacity = '1';
  setTimeout(() => { toast.style.transition='opacity 0.5s'; toast.style.opacity='0'; }, 1500);
}

/* ==================== AI 智能复核（DeepSeek 增强层） ==================== */

const DS_API_KEY_STORAGE = 'ds_api_key';
const DS_API_ENDPOINT = '/api/deepseek';  // 边缘函数（EdgeOne 等）：未填 Key 时由服务端使用演示 Key
const DS_DIRECT_ENDPOINT = 'https://api.deepseek.com/chat/completions'; // 用户自填 Key 时浏览器直连（已验证支持 CORS，纯静态部署也能用）
const DS_MODEL = 'deepseek-chat';
const DS_DEMO_KEY = 'sk-0a569b1153ec44d68529131a45e1a389'; // 内置演示 Key，所有人开箱即用

// 最近一次词库检测的上下文（由 runCheck 写入，供 AI 复核读取）
let lastCheckState = null;

// AI 返回的改写文案缓存（供"一键复制"使用，避免拼接进 onclick 属性）
let lastRewrittenTexts = [];

/**
 * 打开 API 设置浮层，并回填已保存的 Key。
 */
function openApiSettings() {
  const input = document.getElementById('apiKeyInput');
  input.value = localStorage.getItem(DS_API_KEY_STORAGE) || '';
  document.getElementById('apiModalMask').classList.remove('hidden');
  input.focus();
}

/**
 * 关闭 API 设置浮层。
 */
function closeApiSettings() {
  document.getElementById('apiModalMask').classList.add('hidden');
}

/**
 * 保存 API Key 到 localStorage 并刷新状态标识。
 */
function saveApiKey() {
  const key = document.getElementById('apiKeyInput').value.trim();
  if (!key) {
    showToast('请输入有效的 API Key');
    return;
  }
  localStorage.setItem(DS_API_KEY_STORAGE, key);
  loadApiKey();
  closeApiSettings();
  showToast('API Key 已保存（仅存本机浏览器）');
}

/**
 * 清除已保存的 API Key。
 */
function clearApiKey() {
  if (!confirm("确定要清除API Key吗？")) return;
  localStorage.removeItem(DS_API_KEY_STORAGE);
  document.getElementById('apiKeyInput').value = '';
  loadApiKey();
  showToast('API Key 已清除');
}

/**
 * 页面加载时读取 Key 并刷新"已配置/未配置"状态。
 */
function loadApiKey() {
  const key = localStorage.getItem(DS_API_KEY_STORAGE);
  const status = document.getElementById('apiKeyStatus');
  if (key) {
    status.textContent = '自有 Key ✓';
    status.classList.add('configured');
  } else {
    status.textContent = '已内置演示 Key';
    status.classList.remove('configured');
    status.classList.add('demo');
  }
}

/**
 * 构造发给 DeepSeek 的 user 提示词。
 * @param {string} text 原始文案
 * @param {string} typeName 产品类型中文名
 * @param {Array} violations runCheck 产出的词库命中数组
 * @returns {string}
 */
function buildAiUserPrompt(text, typeName, violations, platformName) {
  let hitSummary = '（词库未命中任何违规词）';
  if (violations && violations.length > 0) {
    hitSummary = violations.map((v, i) => {
      const legal = (v.legalBasis && v.legalBasis.length > 0)
        ? v.legalBasis.map(l => `《${l.law_name}》${l.article || ''}`).join('；')
        : '无';
      const alts = (v.alternatives && v.alternatives.length > 0) ? v.alternatives.join('、') : '无';
      return `${i + 1}. 命中词："${v.word}" | 等级：${v.riskLevel} | 法规依据：${legal} | 建议替换：${alts}`;
    }).join('\n');
  }

  return `请对以下营销文案做语义级合规复核（投放平台：${platformName || '未指定'}）。

【产品类型】${typeName}
【投放平台】${platformName || '未指定'}

【原始文案】
${text}

【词库已命中项（已识别，无需重复）】
${hitSummary}

【任务要求】
1. missed_risks：只列出词库可能【漏掉】的语义级/擦边风险，例如：暗示疗效、绝对化表述变体、误导性表述、虚假宣传、违规承诺、谐音/拆字变体等。不要重复上面词库已命中的项。若没有漏网风险，missed_risks 返回空数组 []。

2. rewritten_texts：给出【5 条】基于原话术改写的合规文案，每条独立成篇可直接使用。5条必须覆盖5种不同的投放场景，不允许场景重复。优先匹配平台为"${platformName || '电商'}"的合规规则。
   场景选项（每条选一个不同场景）：
   - 京东商品详情页主标题
   - 京东商品详情页卖点
   - 抖音/快手直播口播脚本
   - 小红书种草笔记
   - 微信朋友圈广告文案
   - 京东主图/轮播图标语
   - 搜索广告标题（直通车等）
   - 短视频口播文案
   每条文案包含：text（文案正文）、score（1-100的合规评分，算法：100-违规词数*15-风险表述*10，90以上为优选）、scene（所选场景的中文名称）。

   改写核心原则：
   - 必须基于原话术改写，保留原文的卖点逻辑、信息结构、品牌名称、产品核心信息，仅替换/修复其中违规和有风险的表述。
   - 不同场景的文案应有明显差异：标题场景精简有力（15-30字）、种草笔记场景细腻走心（80-150字）、直播口播场景口语化有节奏（50-100字）、搜索广告场景突出关键词（10-20字）。

3. overall_advice：一句话总体建议。

【硬性要求】仅返回 JSON，不要输出任何其他内容，结构如下：
{
  "missed_risks": [ { "text": "原文中风险片段", "level": "L1|L2", "reason": "风险说明", "suggestion": "修改建议" } ],
  "rewritten_texts": [
    { "text": "第1条改写文案", "score": 95, "scene": "京东商品详情页主标题" },
    { "text": "第2条改写文案", "score": 92, "scene": "抖音直播口播脚本" },
    { "text": "第3条改写文案", "score": 88, "scene": "小红书种草笔记" },
    { "text": "第4条改写文案", "score": 90, "scene": "微信朋友圈广告文案" },
    { "text": "第5条改写文案", "score": 85, "scene": "京东主图标语" }
  ],
  "overall_advice": "一句话总体建议"
}`;
}

/**
 * 触发 AI 智能复核：校验 Key → 调 DeepSeek → 渲染结果。
 */
async function runAiReview() {
  const resultEl = document.getElementById('aiResult');
  const btn = document.getElementById('aiReviewBtn');

  // ⚠ 关键检查：必须通过本地代理服务器访问，不能用 file:// 协议直接打开
  if (location.protocol === 'file:') {
    resultEl.innerHTML =
      '<div class="ai-error" style="padding:20px;font-size:14px;line-height:1.8;">' +
      '<b>检测到您正在用 file:// 协议直接打开 HTML 文件，AI 复核无法使用！</b><br><br>' +
      '原因：浏览器安全策略禁止 file:// 页面向任何服务器发起网络请求。<br><br>' +
      '<b>解决方法：</b><br>' +
      '① 打开终端/命令行，进入项目目录运行：<code>node proxy-server.js</code><br>' +
      '② 在浏览器地址栏输入 <b style="color:#C41230;font-size:16px;">http://localhost:3456</b> 然后回车<br>' +
      '③ 不要双击 HTML 文件！始终用 http://localhost:3456 访问<br><br>' +
      '<a href="http://localhost:3456" target="_blank" style="display:inline-block;margin-top:8px;padding:10px 24px;background:#C41230;color:#fff;border-radius:8px;text-decoration:none;font-weight:600;">点击这里跳转到正确地址</a></div>';
    return;
  }

  // Key 策略：
  //  - 用户自填了 Key → 优先使用自己的 Key
  //  - 未填 Key     → 使用内置 Demo Key（部署后评委开箱即用）
  //  始终浏览器直连 DeepSeek（已验证支持 CORS），无需代理/边缘函数
  const key = (localStorage.getItem(DS_API_KEY_STORAGE) || '').trim() || DS_DEMO_KEY;
  const endpoint = DS_DIRECT_ENDPOINT;

  if (!lastCheckState || !lastCheckState.text) {
    resultEl.innerHTML = '<div class="ai-error">请先完成"步骤3 开始检测"，再进行 AI 复核。</div>';
    return;
  }

  const typeName = TYPE_NAMES[lastCheckState.productType] || lastCheckState.productType;
  const platformName = PLATFORM_NAMES[currentPlatform] || currentPlatform || '未指定';
  const systemPrompt = '你是资深电商合规审核专家，精通《广告法》《食品安全法》《药品管理法》及各电商平台（京东/抖音/小红书/微信视频号/淘宝/快手/阿里妈妈等）营销规则，输出严谨、可落地。';
  const userPrompt = buildAiUserPrompt(lastCheckState.text, typeName, lastCheckState.violations, platformName);

  btn.disabled = true;
  btn.textContent = '复核中…';
  resultEl.innerHTML = '<div class="ai-loading"><div class="ai-spinner"></div>AI 正在进行语义级复核并生成合规文案，通常需要 10~30 秒…</div>';

  // 请求体：自有 Key 直连时不要把 key 放进 body（改走 Authorization 头），仅边缘函数场景透传 api_key
  const reqBody = {
    model: DS_MODEL,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.3,
    response_format: { type: 'json_object' }
  };
  const fetchHeaders = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + key
  };

  try {
    const resp = await fetch(endpoint, {
      method: 'POST',
      headers: fetchHeaders,
      body: JSON.stringify(reqBody)
    });

    if (!resp.ok) {
      let errMsg = 'HTTP ' + resp.status;
      if (resp.status === 401) {
        errMsg = '401 鉴权失败：Key 无效或已过期。您可点击右上角"⚙ API 设置"填入自己的 Key（或联系管理员更新内置 Key）。';
      } else if (resp.status === 402) {
        errMsg = '402 余额不足：内置演示 Key 额度已用尽，或您的 Key 余额不足。可点击右上角"⚙ API 设置"填入自己的 Key 继续使用。';
      } else if (resp.status === 429) {
        errMsg = '429 请求过于频繁，请稍等片刻后重试。';
      } else {
        let bodyText = '';
        try { bodyText = await resp.text(); } catch (e) { /* 忽略读取失败 */ }
        errMsg = '请求失败（HTTP ' + resp.status + '）：' + (bodyText ? bodyText.slice(0, 200) : '未知错误');
      }
      resultEl.innerHTML = '<div class="ai-error">' + escapeHtml(errMsg) + '</div>';
      return;
    }

    const data = await resp.json();
    const content = data && data.choices && data.choices[0] && data.choices[0].message
      ? data.choices[0].message.content
      : '';
    if (!content) {
      resultEl.innerHTML = '<div class="ai-error">AI 返回内容为空，请重试。</div>';
      return;
    }

    let parsed = null;
    try {
      parsed = JSON.parse(content);
    } catch (e) {
      // 容错：尝试从文本中截取首个 { 到最后一个 } 的片段再解析
      const start = content.indexOf('{');
      const end = content.lastIndexOf('}');
      if (start !== -1 && end > start) {
        try { parsed = JSON.parse(content.substring(start, end + 1)); } catch (e2) { parsed = null; }
      }
    }
    if (!parsed || typeof parsed !== 'object') {
      resultEl.innerHTML = '<div class="ai-error">AI 返回格式异常（非标准 JSON），请点击"🤖 AI 智能复核"重试。</div>';
      return;
    }

    renderAiResult(parsed);
  } catch (err) {
    const netErr = '连接失败（' + escapeHtml(String(err && err.message ? err.message : err)) + '）。';
    resultEl.innerHTML = '<div class="ai-error">' + netErr + '请检查网络是否畅通，或点击右上角"⚙ API 设置"填入您自己的 DeepSeek API Key 重试。</div>';
  } finally {
    btn.disabled = false;
    btn.textContent = '🤖 AI 智能复核';
  }
}

/**
 * 渲染 AI 复核结果（漏网风险 + 改写文案 + 总体建议）。
 * 所有 AI 返回文本插入 DOM 前均经过 sanitizeAiText（清洗乱码字符）+ escapeHtml（防 XSS）。
 * @param {{missed_risks?: Array, rewritten_texts?: string[], overall_advice?: string}} result
 */
function renderAiResult(result) {
  const resultEl = document.getElementById('aiResult');
  const risks = Array.isArray(result.missed_risks) ? result.missed_risks : [];
  let html = '';

  // 1) 漏网风险
  html += '<div class="ai-block-title">🔍 AI 补充发现的语义风险</div>';
  if (risks.length === 0) {
    html += '<div class="ai-ok">AI 未发现新的语义风险 ✓（词库命中项之外没有额外漏网风险）</div>';
  } else {
    html += risks.map(r => {
      const level = (r && r.level === 'L1') ? 'L1' : 'L2';
      const cls = level === 'L1' ? 'v-red' : 'v-yellow';
      const badge = level === 'L1' ? 'L1 拦截级（AI）' : 'L2 预警级（AI）';
      const fragment = escapeHtml(sanitizeAiText(String((r && r.text) || '')));
      const reason = escapeHtml(sanitizeAiText(String((r && r.reason) || '')));
      const suggestion = escapeHtml(sanitizeAiText(String((r && r.suggestion) || '')));
      return `<div class="violation ${cls}">
        <div class="v-header">
          <span class="v-word">${fragment}</span>
          <span class="v-badge">${badge}</span>
        </div>
        <div class="v-field"><span class="v-field-label">风险说明：</span>${reason}</div>
        <div class="v-suggest"><div class="v-suggest-label">修改建议：</div><div style="font-size:13px;">${suggestion}</div></div>
      </div>`;
    }).join('');
  }

  // 2) 改写后的合规文案（基于原话术改写，支持旧格式纯字符串和新格式{text,score,scene}）
  const rawArr = Array.isArray(result.rewritten_texts) ? result.rewritten_texts : [];
  if (rawArr.length > 0) {
    // 兼容旧格式（纯字符串数组）和新格式（对象数组）
    const items = [];
    rawArr.forEach(function(item) {
      if (typeof item === 'string') {
        items.push({ text: item.trim(), score: null, scene: null });
      } else if (item && typeof item === 'object') {
        items.push({
          text: sanitizeAiText(String(item.text || '').trim()),
          score: typeof item.score === 'number' ? Math.round(item.score) : null,
          scene: String(item.scene || '').trim()
        });
      }
    });
    var validItems = items.filter(function(it) { return it.text.length > 0; });

    if (validItems.length > 0) {
      // 更新 lastRewrittenTexts 供复制使用
      lastRewrittenTexts = validItems.map(function(it) { return it.text; });

      html += '<div class="ai-block-title">✏️ AI 合规改写文案（共 ' + validItems.length + ' 条 · 覆盖不同投放场景）</div>';

      validItems.forEach(function(item, i) {
        var label = '方案 ' + (i + 1);
        html += '<div class="ai-rewritten-item">';

        // 头部：标签 + 场景 + 评分 + 复制按钮
        html += '<div class="ai-rewritten-head">';
        html += '<span class="ai-rewritten-tag">' + label + '</span>';
        if (item.scene) {
          html += '<span class="ai-scene-tag">' + escapeHtml(item.scene) + '</span>';
        }
        if (item.score !== null) {
          var scoreColor = item.score >= 90 ? 'var(--bi-500)' : item.score >= 75 ? 'var(--hu-500)' : 'var(--seal-500)';
          html += '<span class="ai-score" style="margin-left:auto;margin-right:8px;">';
          html += '<span class="ai-score-num" style="color:' + scoreColor + ';">' + item.score + '</span>';
          html += '<span class="ai-score-label">分</span>';
          html += '</span>';
        }
        html += '<button class="btn ai-copy-btn-small" onclick="copyText(lastRewrittenTexts[' + i + '])">复制</button>';
        html += '</div>';

        // 评分条
        if (item.score !== null) {
          var barColor = item.score >= 90 ? '#3D7A4A' : item.score >= 75 ? '#C97D11' : '#C41230';
          var barBg = item.score >= 90 ? 'rgba(61,122,74,0.12)' : item.score >= 75 ? 'rgba(201,125,17,0.12)' : 'rgba(196,18,48,0.12)';
          html += '<div class="ai-score-bar" style="background:' + barBg + ';">';
          html += '<div class="ai-score-fill" style="width:' + item.score + '%;background:' + barColor + ';"></div>';
          html += '</div>';
        }

        // 文案内容
        html += '<div class="ai-rewritten">' + escapeHtml(item.text) + '</div>';
        html += '</div>';
      });

      html += '<div class="ai-rewritten-bar"><button class="btn btn-ink" onclick="copyAllRewritten()">📋 一键复制全部 ' + validItems.length + ' 条</button></div>';
    }
  }

  // 3) 总体建议
  const advice = sanitizeAiText(String(result.overall_advice || '').trim());
  if (advice) {
    html += '<div class="ai-advice">💡 总体建议：' + escapeHtml(advice) + '</div>';
  }

  html += '<div class="ai-hint" style="margin-top:12px;">以上为 AI 辅助判断，仅供参考；最终合规判定请以京东平台规则和法律法规为准。</div>';
  resultEl.innerHTML = html;
}

// 复制全部改写文案（多方案合并，带分隔）
function copyAllRewritten() {
  if (!lastRewrittenTexts || lastRewrittenTexts.length === 0) {
    showToast('暂无可复制的文案');
    return;
  }
  const all = lastRewrittenTexts.map((t, i) => '【方案 ' + (i + 1) + '】\n' + t).join('\n\n');
  copyText(all);
}

