/* ============ 3 栏 UI 渲染桥接 ============ */
function renderNewUI(text, violations, matchedRanges) {
  // 1) 摘要徽章
  const l1 = violations.filter(v => v.riskLevel === 'L1').length;
  const l2 = violations.filter(v => v.riskLevel === 'L2').length;
  const total = l1 + l2;
  const badge = document.getElementById('riskBadge');
  badge.innerHTML = '⚠ 检出 ' + total + ' 处风险';
  badge.className = 'risk-badge ' + (total > 0 ? 'amber' : 'green');
  document.getElementById('riskCount').textContent = total + '条待处理';

  // 2) 中间栏：原标题（带高亮）
  const reviewContent = document.getElementById('reviewContent');
  if (!text || !text.trim()) {
    reviewContent.innerHTML = '<div class="empty-state"><span class="icon">📋</span>暂无内容</div>';
  } else {
    let highlighted = '';
    if (matchedRanges.length === 0) {
      highlighted = escapeHtml(text);
    } else {
      const sorted = matchedRanges.slice().sort((a,b) => a.start - b.start);
      const seen = new Set();
      let lastEnd = 0;
      sorted.forEach(r => {
        const key = r.start + '-' + r.end;
        if (seen.has(key)) return;
        seen.add(key);
        if (r.start > lastEnd) highlighted += escapeHtml(text.substring(lastEnd, r.start));
        const cls = r.risk === 'L1' ? 'l1' : 'l2';
        highlighted += '<span class="hl ' + cls + '">' + escapeHtml(text.substring(r.start, r.end)) + '</span>';
        lastEnd = r.end;
      });
      highlighted += escapeHtml(text.substring(lastEnd));
    }

    // 风险标签统计
    const l1Words = violations.filter(v => v.riskLevel === 'L1').map(v => v.word);
    const l2Words = violations.filter(v => v.riskLevel === 'L2').map(v => v.word);
    const l1Set = new Set(l1Words); const l2Set = new Set(l2Words);
    const l1Count = l1Set.size;
    const l2Count = l2Set.size;

    reviewContent.innerHTML = `
      <div class="review-card">
        <div class="review-title-line">
          <strong>原标题：</strong>${highlighted}
        </div>
        <div class="risk-tags">
          ${l1Count > 0 ? '<span class="risk-tag l1">高风险词 × ' + l1Count + '</span>' : ''}
          ${l2Count > 0 ? '<span class="risk-tag l2">中风险词 × ' + l2Count + '</span>' : ''}
          ${total === 0 ? '<span class="risk-tag" style="background:#F0FFF4;color:#1A5C2A;">未发现风险 ✓</span>' : ''}
        </div>
      </div>
    `;
  }

  // 3) 右栏：风险卡片列表
  const riskList = document.getElementById('riskList');
  if (violations.length === 0) {
    riskList.innerHTML = '<div class="empty-state" style="padding:30px 10px;"><span class="icon" style="font-size:24px;">✓</span>未发现风险</div>';
  } else {
    // 去重 + 排序
    const unique = [];
    const seen = new Set();
    violations.forEach(v => {
      const key = v.word + '|' + v.riskLevel;
      if (seen.has(key)) return;
      seen.add(key);
      unique.push(v);
    });
    unique.sort((a, b) => {
      if (a.riskLevel !== b.riskLevel) return a.riskLevel === 'L1' ? -1 : 1;
      return a.position - b.position;
    });

    riskList.innerHTML = unique.slice(0, 50).map(v => {
      const lvl = v.riskLevel;
      const lvlName = lvl === 'L1' ? '高危' : '中危';
      const dotCls = lvl === 'L1' ? 'l1' : 'l2';
      const legal = (v.legalBasis && v.legalBasis.length > 0)
        ? '<div class="risk-detail"><span class="risk-detail-label">违规依据</span>' + escapeHtml(sanitizeAiText(v.legalBasis[0].law_name)) + (v.legalBasis[0].article ? ' ' + escapeHtml(v.legalBasis[0].article) : '') + '：' + escapeHtml(v.legalBasis[0].content || '') + '</div>'
        : '';
      const alts = (v.alternatives && v.alternatives.length > 0)
        ? '<div class="risk-suggest" onclick="copyText(\'' + String(v.alternatives[0]).replace(/'/g, "\\'") + '\')">建议替换：<strong>' + escapeHtml(v.alternatives[0]) + '</strong></div>'
        : (lvl === 'L1' ? '<div class="risk-suggest">建议直接删除该词</div>' : '');
      const desc = v.description ? escapeHtml(v.description) : '';
      return '<div class="risk-card ' + dotCls + '">' +
        '<div class="risk-head">' +
          '<div class="risk-word"><span class="risk-dot"></span>' + escapeHtml(v.word) + '</div>' +
          '<span class="risk-level">' + lvlName + '</span>' +
        '</div>' +
        (desc ? '<div class="risk-desc">' + desc + '</div>' : '') +
        legal + alts +
      '</div>';
    }).join('');
  }
}

