// ============ 最近上传记录 (localStorage 持久化) ============
var RECENT_KEY = 'ejiaotool_recent_uploads';

function loadRecentList() {
  try {
    return JSON.parse(localStorage.getItem(RECENT_KEY) || '[]');
  } catch (e) { return []; }
}

function saveRecentList(list) {
  try {
    // 只保留最近 5 条
    var top = list.slice(0, 5);
    localStorage.setItem(RECENT_KEY, JSON.stringify(top));
  } catch (e) {}
}

function recordRecentUpload(name, size, kind, text) {
  // kind: 'doc' | 'image', text: 可选的文本缓存（用于一键加载）
  var list = loadRecentList();
  // 去重（同名文件）
  list = list.filter(function(it) { return it.name !== name; });
  list.unshift({
    name: name,
    size: size,
    kind: kind,
    text: text ? text.substring(0, 2000) : null,
    ts: Date.now()
  });
  saveRecentList(list);
  renderRecentList();
}

function formatSize(bytes) {
  if (!bytes) return '';
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / 1024 / 1024).toFixed(1) + ' MB';
}

function formatTimeAgo(ts) {
  var diff = Math.floor((Date.now() - ts) / 1000);
  if (diff < 60) return diff + ' 秒前';
  if (diff < 3600) return Math.floor(diff / 60) + ' 分钟前';
  if (diff < 86400) return Math.floor(diff / 3600) + ' 小时前';
  return Math.floor(diff / 86400) + ' 天前';
}

function renderRecentList() {
  var el = document.getElementById('recentUploadList');
  if (!el) return;
  var list = loadRecentList();
  if (list.length === 0) {
    el.innerHTML = '<div class="recent-empty" style="font-size:11px;color:var(--ink-300);padding:10px 4px;text-align:center;font-family:var(--font-serif);">暂无上传记录</div>';
    return;
  }
  var docSvg = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>';
  var imgSvg = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle></svg>';
  el.innerHTML = list.map(function(it, idx) {
    var icon = it.kind === 'image' ? imgSvg : docSvg;
    return '<div class="recent-item" onclick="loadRecentByIdx(' + idx + ')" title="' + escapeHtml(it.name) + '">' +
      '<div class="recent-icon">' + icon + '</div>' +
      '<div class="recent-info">' +
        '<div class="recent-name">' + escapeHtml(it.name) + '</div>' +
        '<div class="recent-time">' + it.size + ' · ' + formatTimeAgo(it.ts) + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
}

function loadRecentByIdx(idx) {
  var list = loadRecentList();
  var item = list[idx];
  if (!item) return;
  if (item.kind === 'image') {
    showToast('该文件为图片，需重新上传进行 OCR 识别');
  } else {
    showToast('该文件存储在本地浏览器中，请重新上传以加载完整内容');
  }
  // 真正可用：把保存的文本片段填入（如果有缓存）
  if (item.text) {
    document.getElementById('inputText').value = item.text;
    document.getElementById('charCount').textContent = item.text.length + ' 字';
    if (!currentProductType) currentProductType = 'regular_food';
    runCheckFromInput(item.text);
    showToast('已加载最近上传：' + item.name);
  }
}

