// 剪贴板粘贴图片 → 打开 OCR 弹窗
async function handlePasteUpload() {
  try {
    var items = await navigator.clipboard.read();
    for (var item of items) {
      for (var type of item.types) {
        if (type.startsWith('image/')) {
          var blob = await item.getType(type);
          var file = new File([blob], 'clipboard.png', { type: type });
          loadOcrImage(file);
          // 显示 OCR 弹窗
          document.getElementById('ocrModal').style.display = '';
          showOcrSection('preview');
          return;
        }
      }
    }
    showToast('剪贴板中没有图片，请先截图或复制图片');
  } catch (e) {
    showToast('无法访问剪贴板，请使用"选择文件"上传图片');
  }
}

/**
 * 处理物料上传：TXT/DOCX → 填文本 + 自动检测；图片 → OCR
 */
function handleFileUpload(event) {
  var file = event.target.files[0];
  if (!file) return;

  var name = file.name.toLowerCase();
  var isImage = file.type.startsWith('image/') || /\.(jpg|jpeg|png|gif|webp|bmp)$/.test(name);
  var isDoc = /\.docx?$/.test(name);
  var isTxt = file.type === 'text/plain' || /\.txt$/.test(name);

  showToast('正在读取文件…');

  if (isImage) {
    recordRecentUpload(file.name, formatSize(file.size), 'image');
    // 图片 → 触发 OCR
    openOcrModal();
    event.target.value = '';
    return;
  }

  if (isTxt) {
    // TXT 文件 → FileReader 读取
    var reader = new FileReader();
    reader.onload = function(e) {
      var text = e.target.result;
      document.getElementById('inputText').value = text;
      document.getElementById('charCount').textContent = text.length + ' 字';
      recordRecentUpload(file.name, formatSize(file.size), 'doc', text);
      showToast('已导入 TXT 文件（' + file.name + '），开始检测…');
      if (!currentProductType) currentProductType = 'regular_food';
      runCheckFromInput(text);
      event.target.value = '';
    };
    reader.onerror = function() { showToast('文件读取失败'); event.target.value = ''; };
    reader.readAsText(file, 'UTF-8');
    return;
  }

  if (isDoc) {
    // DOCX 是 ZIP 压缩的 XML，需用 JSZip 解压后读取 word/document.xml
    if (typeof JSZip === 'undefined') {
      var dlc2=document.getElementById("docxLoader");if(dlc2)dlc2.remove();showToast('JSZip 库未加载，请检查网络');
      event.target.value = '';
      return;
    }
    var docxLoader = document.createElement("div");docxLoader.id="docxLoader";docxLoader.style.cssText="position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(0,0,0,0.75);color:#fff;padding:20px 32px;border-radius:12px;z-index:10000;display:flex;align-items:center;gap:12px;font-size:14px";docxLoader.innerHTML="<span style=\"display:inline-block;width:16px;height:16px;border:2px solid #fff;border-top-color:transparent;border-radius:50%;animation:spin 0.8s linear infinite\"></span>正在解析 DOCX...";document.body.appendChild(docxLoader);JSZip.loadAsync(file).then(function(zip) {
      return zip.file('word/document.xml').async('string');
    }).then(function(xmlStr) {
      // 用 DOMParser 解析 XML
      var parser = new DOMParser();
      var xmlDoc = parser.parseFromString(xmlStr, 'text/xml');
      // 提取所有 <w:t> 元素（段落和文本块中的文本节点）
      var wts = xmlDoc.getElementsByTagName('w:t');
      var lines = [];
      var currentPara = '';
      // 遍历段落 <w:p> 来保留段落结构
      var paras = xmlDoc.getElementsByTagName('w:p');
      for (var i = 0; i < paras.length; i++) {
        var paraText = '';
        var ts = paras[i].getElementsByTagName('w:t');
        for (var j = 0; j < ts.length; j++) {
          paraText += ts[j].textContent;
        }
        if (paraText.trim()) lines.push(paraText);
      }
      var text = lines.join('\n');
      if (!text || text.trim().length === 0) {
        showToast('DOCX 中未找到文字内容');
        event.target.value = '';
        return;
      }
      document.getElementById('inputText').value = text.substring(0, 10000);
      document.getElementById('charCount').textContent = text.length + ' 字';
      recordRecentUpload(file.name, formatSize(file.size), 'doc', text);
      showToast('已导入 DOCX 文件（' + file.name + '，共 ' + text.length + ' 字），开始检测…');
      if (!currentProductType) currentProductType = 'regular_food';
      runCheckFromInput(text.substring(0, 10000));
      event.target.value = '';
    }).catch(function(err) {
      showToast('DOCX 解析失败：' + (err.message || '文件格式异常'));
      event.target.value = '';
    });
    return;
  }

  showToast('不支持的文件格式，请上传 TXT / DOCX / 图片');
  event.target.value = '';
}

/**
 * 直接对输入文本跑检测（不依赖按钮）
 */
function runCheckFromInput(text) {
  if (!text || !text.trim()) return;
  if (!currentProductType) currentProductType = 'regular_food';
  const violations = [];
  const matchedRanges = [];

  LEXICON.entries.forEach(entry => {
    if (currentPlatform !== '全部渠道') {
      const eps = entry.platforms || [];
      if (!eps.includes('全部') && !eps.includes(currentPlatform)) return;
    }
    const matchWords = [entry.word];
    if (entry.variants && Array.isArray(entry.variants)) matchWords.push(...entry.variants);
    const ptr = entry.product_type_rules || {};
    const typeRule = ptr[currentProductType];
    if (!typeRule) return;
    const riskLevel = typeRule.risk_level;
    if (riskLevel !== 'L1' && riskLevel !== 'L2') return;
    const checked = new Set();
    matchWords.forEach(word => {
      if (checked.has(word)) return;
      checked.add(word);
      let idx = text.indexOf(word);
      while (idx !== -1) {
        violations.push({
          word: word, mainWord: entry.word, riskLevel: riskLevel,
          category: entry.category_l2, description: entry.description || '',
          legalBasis: entry.legal_basis || [], note: typeRule.note || '',
          alternatives: getAlternatives(entry, currentProductType),
          whitelist: entry.white_list_contexts || [],
          position: idx, length: word.length, entryId: entry.id
        });
        matchedRanges.push({ start: idx, end: idx + word.length, risk: riskLevel, word: word });
        idx = text.indexOf(word, idx + word.length);
      }
    });
  });

  violations.sort((a, b) => {
    if (a.riskLevel !== b.riskLevel) return a.riskLevel === 'L1' ? -1 : 1;
    return a.position - b.position;
  });

  // 旧 render 函数兼容
  const l1Count = violations.filter(v => v.riskLevel === 'L1').length;
  const l2Count = violations.filter(v => v.riskLevel === 'L2').length;
  renderSummary(l1Count, l2Count);
  renderViolations(violations);
  renderPreview(text, matchedRanges);

  // 新 UI 渲染
  renderNewUI(text, violations, matchedRanges);

  // 兼容旧 AI 复核
  lastCheckState = { text: text, productType: currentProductType, violations: violations };
  document.getElementById('aiResult').innerHTML = '';
  document.getElementById('aiReviewBtn').disabled = false;
  document.getElementById('aiReviewBtn').textContent = '🤖 AI 智能复核';
}

// 修改 loadApiKey 适配新 pill
