// === Floating button drag ===
(function() {
  var fab = null;
  var isDragging = false;
  var startX = 0, startY = 0;
  var startLeft = 0, startTop = 0;
  var hasMoved = false;
  var DRAG_THRESHOLD = 5;

  function initDrag() {
    fab = document.getElementById('chatFab');
    if (!fab) { setTimeout(initDrag, 200); return; }

    // Restore saved position
    try {
      var saved = JSON.parse(localStorage.getItem('chatFabPos') || '{}');
      if (saved.left !== undefined && saved.top !== undefined) {
        fab.style.left = saved.left + 'px';
        fab.style.top = saved.top + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
      }
    } catch(e) {}

    fab.addEventListener('mousedown', onDragStart);
    fab.addEventListener('touchstart', onDragStart, { passive: false });
  }

  function onDragStart(e) {
    var point = e.touches ? e.touches[0] : e;
    var rect = fab.getBoundingClientRect();
    startX = point.clientX;
    startY = point.clientY;
    startLeft = rect.left;
    startTop = rect.top;
    hasMoved = false;

    document.addEventListener('mousemove', onDragMove);
    document.addEventListener('mouseup', onDragEnd);
    document.addEventListener('touchmove', onDragMove, { passive: false });
    document.addEventListener('touchend', onDragEnd);
  }

  function onDragMove(e) {
    var point = e.touches ? e.touches[0] : e;
    var dx = point.clientX - startX;
    var dy = point.clientY - startY;

    if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) {
      if (!isDragging) {
        isDragging = true;
        fab.classList.add('dragging');
      }
      e.preventDefault();
    }

    if (isDragging) {
      var newLeft = Math.max(0, Math.min(window.innerWidth - fab.offsetWidth, startLeft + dx));
      var newTop = Math.max(0, Math.min(window.innerHeight - fab.offsetHeight, startTop + dy));
      fab.style.left = newLeft + 'px';
      fab.style.top = newTop + 'px';
      fab.style.right = 'auto';
      fab.style.bottom = 'auto';
      hasMoved = true;
    }
  }

  function onDragEnd(e) {
    document.removeEventListener('mousemove', onDragMove);
    document.removeEventListener('mouseup', onDragEnd);
    document.removeEventListener('touchmove', onDragMove);
    document.removeEventListener('touchend', onDragEnd);

    if (isDragging) {
      fab.classList.remove('dragging');
      // Save position
      try {
        var rect = fab.getBoundingClientRect();
        localStorage.setItem('chatFabPos', JSON.stringify({ left: Math.round(rect.left), top: Math.round(rect.top) }));
      } catch(e) {}
      isDragging = false;
    }
  }

  // Expose hasMoved check for toggleChat
  window._fabHasMoved = function() { return hasMoved; };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDrag);
  } else {
    initDrag();
  }
})();

function toggleChat() {
  chatOpen = !chatOpen;
  var panel = document.getElementById('chatPanel');
  var fab = document.getElementById('chatFab');
  if (chatOpen) {
    panel.classList.add('open');
    fab.classList.remove('pulse');
    setTimeout(function() { document.getElementById('chatInput').focus(); }, 300);
    scrollChatBottom();
  } else {
    panel.classList.remove('open');
    fab.classList.add('pulse');
  }
}

function chatKeydown(e) {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendChat();
  }
}

function sendChat() {
  if (chatLoading) return;
  var input = document.getElementById('chatInput');
  var text = input.value.trim();
  if (!text) return;

  input.value = '';
  input.style.height = 'auto';
  chatLoading = true;
  document.getElementById('chatSend').disabled = true;

  appendMessage('user', text);
  showTyping();

  callDeepSeekChat(text)
    .then(function(reply) {
      removeTyping();
      appendMessage('bot', reply);
    })
    .catch(function(err) {
      removeTyping();
      appendMessage('bot', '抱歉，请求失败：' + (err.message || '网络异常') + '。请稍后重试或检查 API Key 设置。');
    })
    .finally(function() {
      chatLoading = false;
      document.getElementById('chatSend').disabled = false;
    });
}

function appendMessage(role, text) {
  var body = document.getElementById('chatBody');
  var div = document.createElement('div');
  div.className = 'chat-msg ' + role;
  if (role === 'bot') {
    div.innerHTML = '<div class="msg-label">AI 助手</div>' + escapeChat(text);
  } else {
    div.innerHTML = '<div class="msg-label">你</div>' + escapeChat(text);
  }
  body.appendChild(div);
  scrollChatBottom();
}

function showTyping() {
  var body = document.getElementById('chatBody');
  var div = document.createElement('div');
  div.className = 'chat-msg typing';
  div.id = 'chatTyping';
  div.innerHTML = '<span></span><span></span><span></span>';
  body.appendChild(div);
  scrollChatBottom();
}

function removeTyping() {
  var el = document.getElementById('chatTyping');
  if (el) el.remove();
}

function scrollChatBottom() {
  var body = document.getElementById('chatBody');
  setTimeout(function() { body.scrollTop = body.scrollHeight; }, 50);
}

function escapeChat(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');
}

async function callDeepSeekChat(userMsg) {
  var key = (localStorage.getItem(DS_API_KEY_STORAGE) || '').trim() || DS_DEMO_KEY;
  var endpoint = DS_DIRECT_ENDPOINT;
  var messages = [
    { role: 'system', content: CHAT_SYSTEM_PROMPT },
    { role: 'user', content: userMsg }
  ];

  var resp = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + key
    },
    body: JSON.stringify({
      model: DS_MODEL,
      messages: messages,
      temperature: 0.5,
      max_tokens: 600
    })
  });

  if (!resp.ok) {
    var errText = '';
    try { errText = await resp.text(); } catch (e) {}
    if (resp.status === 401) throw new Error('API Key 无效，请在右上角「API 设置」中更新');
    if (resp.status === 402) throw new Error('API 余额不足，请充值或更换 Key');
    if (resp.status === 429) throw new Error('请求过于频繁，请稍后重试');
    throw new Error('HTTP ' + resp.status + (errText ? ' ' + errText.slice(0, 80) : ''));
  }

  var data = await resp.json();
  var content = data && data.choices && data.choices[0] && data.choices[0].message
    ? data.choices[0].message.content
    : '';

  if (!content) throw new Error('AI 返回内容为空，请重试');

  return content;
}

