  var stats = { L1: 0, L2: 0, L3: 0 };
  var cats = {};
  kbEntries.forEach(function(e) {
    stats[e.risk_level] = (stats[e.risk_level] || 0) + 1;
    var c = e.category_l1 || '其他';
    cats[c] = (cats[c] || 0) + 1;
  });
  document.getElementById('kbStatL1').textContent = stats.L1 || 0;
  document.getElementById('kbStatL2').textContent = stats.L2 || 0;
  document.getElementById('kbCntL1').textContent = stats.L1 || 0;
  document.getElementById('kbCntL2').textContent = stats.L2 || 0;
  document.getElementById('kbCntL3').textContent = stats.L3 || 0;

  var catHtml = '<button class="kb-filter-chip active" data-kb="cat" data-kbval="all">全部 <span style="float:right;font-size:11px;color:var(--ink-300);">' + kbEntries.length + '</span></button>';
  Object.keys(cats).sort(function(a, b) { return cats[b] - cats[a]; }).forEach(function(cat) {
    catHtml += '<button class="kb-filter-chip" data-kb="cat" data-kbval="' + cat + '">' + (kbCatNames[cat] || cat) + ' <span style="float:right;font-size:11px;color:var(--ink-300);">' + cats[cat] + '</span></button>';
  });
  document.getElementById('kbCatList').innerHTML = catHtml;
  bindKbFilters();
